"use client";

import { useEffect, useMemo, useState } from "react";

import FiltersBar from "@/components/inventory/FiltersBar";
import InventoryTable from "@/components/inventory/InventoryTable";
import AppHeader from "@/components/layout/AppHeader";
import PageContainer from "@/components/layout/PageContainer";
import FloatingActionButton from "@/components/ui/FloatingActionButton";
import { useInventorySelection } from "@/store/inventorySelection.store";

type InventoryItem = {
  id: string;
  name: string;
  rarity: string;
  price: string | number;
  location: string;
};

async function fetchInventory() {
  const response = await fetch("/api/inventory");

  if (!response.ok) {
    return [];
  }

  return response.json();
}

export default function InventoryPage() {
  const selectedCount = useInventorySelection((state) => state.selected.size);
  const [, setItems] = useState<InventoryItem[]>([]);
  const store = useMemo(() => ({ setItems }), [setItems]);

  useEffect(() => {
    const loadInventory = async () => {
      const result = await fetchInventory();
      const items = Array.isArray(result) ? result : result?.items ?? [];

      store.setItems(items);
    };

    void loadInventory();
  }, [store]);

  return (
    <PageContainer>
      <AppHeader />
      <FiltersBar />
      <InventoryTable />
      <FloatingActionButton
        label="Move selected →"
        onClick={() => {}}
        visible={selectedCount > 0}
      />
    </PageContainer>
  );
}
